xc_mapping_rows(a65b16505ed6c3,[]).
x_comment(x_ObtainingPermission,"The collection of events in which one #$Agent-PartiallyTangible gets permission from another #$Agent-PartiallyTangible to do something.") :- x_cid(a65b16505ed6c4).
xc_microtheory(a65b16505ed6c4,x_UniversalVocabularyMt).
