xc_mapping_rows(a65b16505ed6f4,[]).
x_comment(x_maritalStatus,"(#$maritalStatus PERSON STATUS) means that the #$Person PERSON has the #$PersonTypeByMaritalStatus STATUS.  For example, (#$maritalStatus #$BillClinton #$Married).  The marital status of a person depends on whether, and when, that person was married to another person, and how the marriage ended.") :- x_cid(a65b16505ed6f5).
xc_microtheory(a65b16505ed6f5,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed6f5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
