xc_mapping_rows(a65b16505ed756,[]).
x_comment('x_SupportGroupFn-FeelingType',"#$SupportGroupFn-FeelingType takes as argument any instance TYPE of #$EmotionalQuantityType and returns the collection of all support groups for persons who have some degree of that quantity.  For example, (#$SupportGroupFn-FeelingType #$Panic) denotes the collection of all support groups for persons who have some quantity of #$Panic.") :- x_cid(a65b16505ed757).
xc_microtheory(a65b16505ed757,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed757,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
