xc_mapping_rows(a65b16505ed7bf,[]).
x_comment(x_Repetition,"A specialization of #$ContinuedActivity.  Each instance of #$ResumedActivity is an event in which an agent resumes the performance of some discontinuous event (cf. #$temporallyContinuousDuring).") :- x_cid(a65b16505ed7c0).
xc_microtheory(a65b16505ed7c0,x_UniversalVocabularyMt).
