xc_mapping_rows(a65b16505ed91d,[]).
x_comment(x_BlockingAnInternationalWaterway,"A collection of events in which some #$Agent-PartiallyTangible interferes with traffic on international waters. This may be accomplished with some physical barrier, or with the threat of violence to traffic travelling in that area. Generally, UN regulations prohibit this kind of action.") :- x_cid(a65b16505ed91e).
xc_microtheory(a65b16505ed91e,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed91e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
