x_comment(x_ComedyTVShow,"Instances of #$ComedyTVShow are #$TVShow-IBTs intended to be funny, e.g. 'Saturday            Night Live' or 'Friends'.") :- x_cid(a65b16505ed949).
xc_microtheory(a65b16505ed949,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed949,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
