xc_mapping_rows(a65b16505ed94d,[]).
x_comment(x_telegramServiceUsed,"(#$telegramServiceUsed SENDING SERVICE) means that SERVICE, an instance of #$DeliveryServiceEvent was used to send the telegram sent in SENDING, an instance of #$SendingATelegram.") :- x_cid(a65b16505ed94e).
xc_microtheory(a65b16505ed94e,x_UniversalVocabularyMt).
