xc_mapping_rows(a65b16505ed953,[]).
x_comment(x_numberOfDiscountPointsOnLoan,"(#$numberOfDiscountPointsOnLoan LOAN N) identifies N as the number of \"points\" on the instance of #$LoanAgreement LOAN that are paid to reduce the interest rate of the loan (c.f., #$interestRate).  One point translates to 1 percent of the loan amount (c.f., #$initialLoanAmount).  To represent the points on a loan as a monetary amount, user #$discountPointsValueOnLoan.") :- x_cid(a65b16505ed954).
xc_microtheory(a65b16505ed954,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed954,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505ed954,9101).
xc_kb_names(a65b16505ed954,[]).
xc_mapping_rows(a65b16505ed954,[]).
x_comment(x_Prophet,"The collection of leaders / teachers who predict the future \n\n(e.g., make a #$MakingAPrediction) regarding the actions of God/the gods.") :- x_cid(a65b16505ed955).
xc_microtheory(a65b16505ed955,x_UniversalVocabularyMt).
