xc_mapping_rows(a65b16505ed955,[]).
x_comment(x_SoftwareTestOrType,"Each instance of #$SoftwareTestOrType is either a collection\nwhose instances are individual software test definitions or an individual test. The meaning of this collection is equivalent to (#$CollectionUnionFn (#$TheSet #$KBContentTest-FullySpecified #$KBContentTestSpecificationType)). ") :- x_cid(a65b16505ed956).
xc_microtheory(a65b16505ed956,x_UniversalVocabularyMt).
xc_source_file(a65b16505ed956,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
