xc_mapping_rows(a65b16505ed9e2,[]).
x_comment(x_loudnessOfEvent,"A #$SensoryAttributeDescriptionPredicate and #$QuantitySlot that relates a #$PhysicalEvent to a #$AcousticNoiseLevel.  (#$loudnessLevel EVENT LEVEL) means that the noise/loudness level of the totality of #$AudibleSounds (see #$loudnessLevel) currently being produced in the course of EVENT is LEVEL.\n<p>\nCf. #$loudnessOfObject.") :- x_cid(a65b16505ed9e3).
xc_microtheory(a65b16505ed9e3,x_UniversalVocabularyMt).
