xc_mapping_rows(a65b16505edac3,[]).
x_comment('x_Atmosphere-UnitOfPressure',"One #$Atmosphere-UnitOfPressure is defined as the average pressure of the earth's atmosphere at sea level.  It is slightly over 1% higher than one #$Bar-UnitOfPressure.") :- x_cid(a65b16505edac4).
xc_microtheory(a65b16505edac4,x_UniversalVocabularyMt).
xc_source_file(a65b16505edac4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
