xc_mapping_rows(a65b16505edacf,[]).
x_comment(x_HydroPoweredTurbine,"The subcollection of #$Turbines use #$FluidFlow-Translation of #$Water to generate #$Electricity.") :- x_cid(a65b16505edad0).
xc_microtheory(a65b16505edad0,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad0,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
