xc_mapping_rows(a65b16505edad1,[]).
x_comment(x_evaluator,"An instance of #$ActorSlot that relates an instance of #$Evaluating to the instances of #$IntelligentAgent who perform the evaluation. (#$evaluator EVALUATION EVALUATOR) says that EVALUATOR does the evaluating EVALUATION.  See also #$evaluee-Direct, #$evaluationInputs, #$evaluationOutputSentences and #$objectOfEvaluation.") :- x_cid(a65b16505edad2).
xc_microtheory(a65b16505edad2,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad2,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
