xc_mapping_rows(a65b16505edad2,[]).
x_comment(x_TwoOrThreeLanesRoadway,"The collection of #$Roadways that have a total of 2 or 3 lanes or tracks, both directions\n\nincluded. This criterion belongs to the US Army's nomenclature for the\n\nrepresentation of roads on large and medium scale maps. See also\n\n#$RoadwayTypeByNumberOfLanes.") :- x_cid(a65b16505edad3).
xc_microtheory(a65b16505edad3,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad3,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505edad3,9869).
xc_kb_names(a65b16505edad3,[]).
xc_mapping_rows(a65b16505edad3,[]).
x_comment(x_advertisingMedium,"A predicate for relating an advertising event to a type of medium (broadly construed) in which advertisements generated by that event, appear. (#$advertisingMedium ADVERTISING IBTTYPE) means instances of #$Advertisement-PCW used in ADVERTISING (see #$advertisementUsed) appear in instances of IBTTYPE, a specialization of #$InformationBearingThing. For example, (#$advertisingMedium NIKEADCAMPAIGN2331 (#$CopyOfCWFn\n\n(#$MediaSeriesNthFn #$Newsweek-TheMagazine 783))) means that advertisements used in NIKEADCAMPAIGN2331 appear in copies of issue 783 of News Week\n\nmagazine. (#$advertisingMedium NIKEADCAMPAIGN2331 (#$BroadcastOfEventTypeFn (#$PlayingFn #$Basketball-TheGame))) means that advertisements used in NIKEADCAMPAIGN2331 appear broadcasts of basketball games.") :- x_cid(a65b16505edad4).
xc_microtheory(a65b16505edad4,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505edad4,9876).
xc_kb_names(a65b16505edad4,[]).
xc_mapping_rows(a65b16505edad4,[]).
x_comment(x_CommunicationWithServiceSpecification,"The collection of complete #$Specifications required to connect two or more #$Artifact-Agentives via a #$MachineProtocol carried over a #$ProtocolTransportMediumType.") :- x_cid(a65b16505edad5).
xc_microtheory(a65b16505edad5,x_UniversalVocabularyMt).
