xc_mapping_rows(a65b16505edad5,[]).
x_comment(x_Disgust,"A feeling of repulsion or aversion towards something considered distasteful or repugnant.  This is a #$Collection --- for an explanation of that, see #$Happiness.  Some more specialized #$EmotionalQuantityTypes than #$Disgust include feelings of #$Abhorrence.") :- x_cid(a65b16505edad6).
xc_microtheory(a65b16505edad6,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
