xc_mapping_rows(a65b16505edad6,[]).
x_comment(x_ComputerTypeByUse,"A collection of collections.  Each instance of #$ComputerTypeByUse is a collection of computers that can be or are\ndesigned to be put to a certain use.  Instances include #$SingleUser-Computer, #$AccountingUse, etc..") :- x_cid(a65b16505edad7).
xc_microtheory(a65b16505edad7,x_UniversalVocabularyMt).
xc_source_file(a65b16505edad7,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
