xc_kb_names(a65b16505edb1b,[]).
xc_mapping_rows(a65b16505edb1b,[]).
x_comment(x_ConceptNodesForTaxonFn,"(#$ConceptNodesForTaxonFn TAXON)\nreturns an instance of #$ConceptFilter that has all and only the nodes in TAXON as nodes.") :- x_cid(a65b16505edb1c).
xc_microtheory(a65b16505edb1c,x_UniversalVocabularyMt).
