xc_mapping_rows(a65b16505edb1d,[]).
x_comment(x_subSitTypesTemporallyDisjointInSitType,"<code>(#$subSitTypesTemporallyDisjointInSitType SIT-TYPE SUBSIT-TYPE1 SUBSIT-TYPE2)</code> means that in any instance <code>SIT</code> of <code>SIT-TYPE</code> (a specialization of #$Situation), if instances <code>SIT1</code> and <code>SIT2</code> of <code>SUBSIT-TYPE1</code> and <code>SUBSIT-TYPE2</code> occur as subsituations, then <code>SIT1</code> and <code>SIT2</code> do not temporally overlap (see also #$temporalBoundsIntersectInSituationType).\n<p>\nNote that <code>(#$subSitTypesTemporallyDisjointInSitType SIT-TYPE SUBSIT-TYPE1 SUBSIT-TYPE2)</code> does not imply that instances of <code>SUBSIT-TYPE1</code> or <code>SUBSIT-TYPE2</code> occur as subsituations of every instance of <code>SIT-TYPE</code>, since <code>SUBSIT-TYPE1</code> and <code>SUBSIT-TYPE2</code> may be merely candidate subsituation types of <code>SIT-TYPE</code> (see #$candidateProperSubSituationTypes).") :- x_cid(a65b16505edb1e).
xc_microtheory(a65b16505edb1e,x_UniversalVocabularyMt).
xc_source_file(a65b16505edb1e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505edb1e,10044).
xc_kb_names(a65b16505edb1e,[]).
xc_mapping_rows(a65b16505edb1e,[]).
x_comment(x_recognizesHoliday,"#$recognizesHoliday is an instance of #$BinaryPredicate that\n\nrelates instances of #$Agent-PartiallyTangible to specializations of #$Holiday.\n\n(#$recognizesHoliday AGENT HOLIDAY) means that AGENT recognizes\n\nHOLIDAY, usually by celebrating in some way.  If AGENT is an instance\n\nof #$LegalAgent, and HOLIDAY is an instance of #$LegalHoliday, AGENT\n\nusually suspends or decreases the intensity of normal official\n\npractices.") :- x_cid(a65b16505edb1f).
xc_microtheory(a65b16505edb1f,x_UniversalVocabularyMt).
xc_source_file(a65b16505edb1f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
