xc_mapping_rows(a65b16505edb27,[]).
x_comment(x_GreenlandPerson,"A person who is a #$citizens of #$Greenland-Polity, or participates in its #$NationalCulture.") :- x_cid(a65b16505edb28).
xc_microtheory(a65b16505edb28,x_UniversalVocabularyMt).
