xc_mapping_rows(a65b16505edb2c,[]).
x_comment(x_GamezProgram,"The collection of #$ComputerGamePrograms that are available to be downloaded (see #$DownloadingAFile).") :- x_cid(a65b16505edb2d).
xc_microtheory(a65b16505edb2d,x_UniversalVocabularyMt).
