xc_mapping_rows(a65b16505edb32,[]).
x_comment(x_hasExistentialStatus,"(#$hasExistentialStatus THING STATUS) means that THING is in the\n\nexistential state described by STATUS, an instance of\n\n#$TemporalThingTypeByExistentialStatus.") :- x_cid(a65b16505edb33).
xc_microtheory(a65b16505edb33,x_UniversalVocabularyMt).
xc_source_file(a65b16505edb33,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
