xc_mapping_rows(a65b16505edc0b,[]).
x_comment(x_RGBFn,"An instance of #$TernaryFunction.  #$RGBFn takes three instances of (#$IntegerFromToFn 0 255) and returns the instance of #$ColorPerceptionCategoryType that has red, green, and blue light in the amounts indicated by the 1st, 2nd, and 3rd arguments, respectively.  See also #$colorHasRGBRedValue, #$colorHasRGBGreenValue, and #$colorHasRGBBlueValue.") :- x_cid(a65b16505edc0c).
xc_microtheory(a65b16505edc0c,x_UniversalVocabularyMt).
