xc_kb_names(a65b16505ee032,[]).
xc_mapping_rows(a65b16505ee032,[]).
x_comment(x_diameterOfAnatomicalFeatureDiagnosed,"A #$BinaryQuantityPredicate used to relate a metrical #$MedicalDiagnosisOrFinding to the diameter of the anatomical feature that it measures.  Assuming that (#$diagnosisSiteType DIAGNOSIS PART-TYPE), that (#$subjectOfDiagnosis DIAGNOSIS SUBJECT), that (#$anatomicalParts SUBJECT PART), that (#$isa SUBJECT ORG-TYPE) and (#$isa PART PART-TYPE), and that (#$uniquePhysicalPartTypes ?ORG-TYPE ?PART-TYPE), then, where (#$diameterOfAnatomicalFeatureDiagnosed DIAGNOSIS DIAMETER) and given that (#$evaluationCorrectness DIAGNOSIS #$True), it follows that (#$diameterOfObject PART DIAMETER) at the time of DIAGNOSIS.") :- x_cid(a65b16505ee033).
xc_microtheory(a65b16505ee033,x_UniversalVocabularyMt).
xc_source_file(a65b16505ee033,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
