xc_mapping_rows(a65b16505eed23,[]).
x_comment(x_PluripotentCell,"#$PluripotentCells are #$StemCells that can differentiate into any cell type of an adult or immature organism (of a given species), but because they lack the ability to produce structures outside the embryo proper, such as the placenta, they can't develop into an entire organism.") :- x_cid(a65b16505eed24).
xc_microtheory(a65b16505eed24,x_UniversalVocabularyMt).
xc_source_file(a65b16505eed24,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
