xc_kb_names(a65b16505eed2f,[]).
xc_mapping_rows(a65b16505eed2f,[]).
x_comment(x_productOfBLO,"<code>(#$productOfBLO BLO PRODUCT)</code> means that <code>BLO</code> is the source of <code>PRODUCT</code>.  For example <code>(#$productOfBLO MapleTree001 MapleSyrup001)</code> means that <code>MapleTree001</code> is the source of <code>MapleSyrup001</code>.") :- x_cid(a65b16505eed30).
xc_microtheory(a65b16505eed30,x_UniversalVocabularyMt).
xc_source_file(a65b16505eed30,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
