xc_microtheory(a65b16505eefa8,x_UniversalVocabularyMt).
xc_source_file(a65b16505eefa8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
