xc_mapping_rows(a65b16505efce9,[]).
x_comment(x_prescriptionSpecifiesTreatmentStartTime,"(#$prescriptionSpecifiesDosageForNthDose SCRIP DATE) states that the #$DrugPrescription-Specification SCRIP asks that first dose of the specified #$DrugTreatmentSequence be taken/administered at DATE.") :- x_cid(a65b16505efcea).
xc_microtheory(a65b16505efcea,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcea,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
