xc_mapping_rows(a65b16505efcea,[]).
x_comment(x_prescriptionSpecifiesAdministrationRouteType,"(#$prescriptionSpecifiesAdministrationRouteType SCRIP ADMIN-TYPE) states that the #$DrugPrescription-Specification SCRIP asks that the drug administered in the specified #$DrugTreatmentSequence be taken/administered in events of ADMIN-TYPE.") :- x_cid(a65b16505efceb).
xc_microtheory(a65b16505efceb,x_UniversalVocabularyMt).
xc_source_file(a65b16505efceb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
