xc_kb_names(a65b16505efcf3,[]).
xc_mapping_rows(a65b16505efcf3,[]).
x_comment(x_sizeOfDose,"(#$sizeOfDose DOSE QUANT) states that the #$DoseOfDrug, DOSE, has the amount QUANT.  Quite frequently, QUANT will be an instance of #$Mass, however some medication dosages may be measured with a different type of quantity.") :- x_cid(a65b16505efcf4).
xc_microtheory(a65b16505efcf4,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcf4,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505efcf4,20046).
xc_kb_names(a65b16505efcf4,[]).
xc_mapping_rows(a65b16505efcf4,[]).
x_comment(x_getNormalizedTraceAtDateByDepthRangeTempRange,"<code>(#$getNormalizedTraceAtDateByDepthRange FIBER DATE N MIN-DEPTH MAX-DEPTH MIN-TEMP MAX-TEMP (#$The2DPoint DEPTH TEMP))</code> means that the DTS fiber <code>FIBER</code> measured the depth/temperature pairs <code>DEPTH</code>/<code>TEMP</code> at regular internals of <code>N</code> meters <code>DATE</code>, where <code>DEPTH</code> is in the interval bounded by <code>MIN-DEPTH</code> and <code>MAX-DEPTH</code> and where <code>TEMP</code> is in the interval bounded by <code>MIN-TEMP</code> and <code>MAX-TEMP</code>.") :- x_cid(a65b16505efcf5).
xc_microtheory(a65b16505efcf5,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcf5,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
xc_source_line(a65b16505efcf5,20047).
xc_kb_names(a65b16505efcf5,[]).
xc_mapping_rows(a65b16505efcf5,[]).
x_comment(x_getNormalizedTraceBetweenDatesByDepthRange,"<code>(#$getNormalizedTraceBetweenDatesByDepthRange  FIBER MIN-DEPTH MAX-DEPTH N START END (The2DPoint DEPTH AVG-TEMP))</code> means that the DTS fiber <code>FIBER</code>  normalized to <code>N</code>-meter interval depths between <code>MIN-DEPTH</code> and <code>MAX-DEPTH</code> measured temperatures that average <code>AVG-TEMP</code> between <code>START</code> and the later date <code>END</code>.") :- x_cid(a65b16505efcf6).
xc_microtheory(a65b16505efcf6,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcf6,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
