xc_mapping_rows(a65b16505efcf7,[]).
x_comment(x_prescriptionSubstitutionOfTherapueticEquivalentAllowed,"A #$UnaryPredicate.  If (#$prescriptionSubstitutionOfTherapueticEquivalentAllowed SCRIP), the #$DrugPrescription-Specification,  SCRIP, is such that the patient may be treated with a drug that is therapeutically equivalent to the prescribed drug (see #$prescribedDrugType), and that treatment will still conform to the specfication of the prescription.") :- x_cid(a65b16505efcf8).
xc_microtheory(a65b16505efcf8,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcf8,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
