xc_mapping_rows(a65b16505efcf9,[]).
x_comment(x_AscendingAlongSurface,"Any process in which an object moves upward along some surface.") :- x_cid(a65b16505efcfa).
xc_microtheory(a65b16505efcfa,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcfa,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
