xc_mapping_rows(a65b16505efcfa,[]).
x_comment(x_ProgramActionRecord,"The collection of all instances of #$ComputerCodeStatement-Atomic that have a standard interpretation as records of program actions, as recorded in #$LogFile instances.") :- x_cid(a65b16505efcfb).
xc_microtheory(a65b16505efcfb,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcfb,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
