x_comment(x_timeStampStringOfProgramActionRecord,"(#$timeStampStringOfProgramActionRecord RECORD STRING) means that STRING is a #$CharacterString denoting the unique timestamp of the #$ProgramActionRecord RECORD.") :- x_cid(a65b16505efcfd).
xc_microtheory(a65b16505efcfd,x_UniversalVocabularyMt).
xc_source_file(a65b16505efcfd,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
