xc_kb_names(a65b16505efcff,[]).
xc_mapping_rows(a65b16505efcff,[]).
x_comment(x_logFileMembers,"(#$logFileMembers LOG-FILE RECORD) means that the #$ProgramActionRecord RECORD is a sub-statement of the #$LogFile LOG-FILE.") :- x_cid(a65b16505efd00).
xc_microtheory(a65b16505efd00,x_UniversalVocabularyMt).
xc_source_file(a65b16505efd00,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
