xc_mapping_rows(a65b16505efd00,[]).
x_comment(x_executionHasLogFile,"(#$executionHasLogFile EXECUTION FILE) means that the #$LogFile FILE records the entirety of EXECUTION (a #$ProgramExecution-Complete) and nothing else.") :- x_cid(a65b16505efd01).
xc_microtheory(a65b16505efd01,x_UniversalVocabularyMt).
