xc_microtheory(a65b16505f0312,x_UniversalVocabularyMt).
xc_source_file(a65b16505f0312,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/UniversalVocabularyMt.part07.krf').
